def logger(func):
    def wrapper():
        print("Function is starting")
        func()
        print("Function is finished")
    return wrapper

@logger
def greet():
    print("Hello")

greet()

def decorator(func):
    def wrapper():
        print("Before")
        func()
        print("After")
    return wrapper

def hello():
    print("Hello")

hello = decorator(hello)
hello()

import time

def measure_time(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"Execution time: {end - start:.6f} seconds")
        return result
    return wrapper

@measure_time
def add(a, b):
    return a + b

result = add(10, 20)
print(result)

def log_call(func):
    def wrapper(*args, **kwargs):
        print("Calling function...")
        result = func(*args, **kwargs)
        return result
    return wrapper

@log_call
def add(a, b):
    return a + b

@log_call
def greet(name, message="Hello"):
    return f"{message}, {name}!"

print(add(2, 3))
print(greet("Abhishek", message="Hi"))

from functools import wraps

def logger(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("Calling function")
        return func(*args, **kwargs)
    return wrapper

@logger
def greet(name):
    """Greets a person."""
    return f"Hello, {name}"

print(greet.__name__)
print(greet.__doc__)

def first(func):
    def wrapper():
        print("First - before")
        func()
        print("First - after")
    return wrapper

def second(func):
    def wrapper():
        print("Second - before")
        func()
        print("Second - after")
    return wrapper

@first
@second
def hello():
    print("Hello")

hello()

class Demo:
    def __enter__(self):
        print("Entering")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        print("Exiting")

with Demo():
    print("Inside block")

class Resource:
    def __enter__(self):
        print("Resource acquired")
        return "My Resource"

    def __exit__(self, exc_type, exc_value, traceback):
        print("Resource released")

with Resource() as value:
    print(value)

class DatabaseConnection:
    def __enter__(self):
        print("Connecting to database")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        print("Closing database connection")

with DatabaseConnection():
    print("Running query")

class IgnoreError:
    def __enter__(self):
        print("Start")

    def __exit__(self, exc_type, exc_value, traceback):
        print("Cleanup")
        if exc_type is ValueError:
            print("ValueError handled")
            return True
        return False

with IgnoreError():
    print("Inside")
    raise ValueError("Something went wrong")

print("Program continues")

from enum import StrEnum

class OrderStatus(StrEnum):
    PENDING = "pending"
    SHIPPED = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"

def update_order(status: OrderStatus):
    if status == OrderStatus.SHIPPED:
        print("Order is on the way")
    elif status == OrderStatus.DELIVERED:
        print("Order delivered")

update_order(OrderStatus.SHIPPED)
